/**
 * Docusaurus plugin: IDE-style API hover for docs code.
 *
 * Consumes an API symbol index (a names JSON generated by the consuming
 * site; see README for the schema) and provides:
 *
 *  - theme components that stamp `data-api-id` onto resolved identifiers
 *    in code blocks (CodeBlock/Line) and render them (Line/Token),
 *  - the shared browser hover runtime, mounted through Root: page-wide
 *    highlight of every instance of a symbol plus a signature/docstring
 *    tooltip, loaded lazily from the info JSON,
 *  - webpack wiring that injects the packed index and the runtime options
 *    into the client bundle as aliased JSON modules (`quickinfo/data` and
 *    `quickinfo/config`), which works under both webpack and rspack.
 *
 * The rehype companion (`quickinfo/rehype`) annotates prose mentions at
 * build time and is registered by the consumer in its markdown config,
 * like any other rehype plugin.
 */
import path from 'path';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import type { LoadContext, Plugin } from '@docusaurus/types';
import { packNames, type NamesJson } from '../lib/names';
import { checkCommonOptions, DEFAULT_INFO_URL, withBase } from '../lib/options';

/** Options for the Docusaurus plugin, passed in `docusaurus.config.js`. */
export interface PluginOptions {
  /**
   * Path to the names JSON your index generator writes, relative to the
   * site directory. Shape:
   * `{ids: string[], bases?: Record<string, string[]>, version?: string}`.
   * @default 'static/quickinfo/names.json'
   */
  dataFile?: string;
  /**
   * URL the runtime fetches the info JSON from, with `?v=<version>`
   * appended from the names JSON. A root-relative URL gets the site's
   * `baseUrl` prefixed.
   * @default '/quickinfo/info.json'
   */
  infoUrl?: string;
  /**
   * Id prefixes that win a short-name collision, e.g. `["max."]` on a site
   * that indexes both MAX symbols and Python stdlib ids. Keeps secondary
   * id sources from changing existing annotations.
   * @default []
   */
  preferPrefixes?: string[];
  /**
   * Language modules to enable for code annotation. Built in: `"python"`.
   * @default ['python']
   */
  languages?: string[];
  /**
   * Route prefixes whose code blocks stay unannotated, under the site's
   * `baseUrl`: pages for another language or another version of the API
   * than the index describes, e.g. `['/stable/', '/api/mojo/']`. Pass the
   * same pages to the rehype pass's `exclude`.
   * @default []
   */
  exclude?: string[];
}

const DEFAULT_DATA_FILE = 'static/quickinfo/names.json';

function readNames(dataPath: string): NamesJson {
  if (!existsSync(dataPath)) return { ids: [] };
  try {
    const names = JSON.parse(readFileSync(dataPath, 'utf8')) as NamesJson;
    if (Array.isArray(names.ids)) return names;
    console.warn(`quickinfo: "${dataPath}" has no "ids" array; hover disabled.`);
  } catch (err) {
    console.warn(
      `quickinfo: "${dataPath}" is not valid JSON (${err instanceof Error ? err.message : err}); hover disabled.`,
    );
  }
  return { ids: [] };
}

/**
 * The Docusaurus plugin. Registers the theme components that annotate code
 * blocks, aliases the packed names JSON and the runtime config into the
 * client bundle, and mounts the hover runtime through `Root`. Prose
 * mentions are annotated by the rehype pass, registered separately.
 *
 * @param context Docusaurus load context; `siteDir` anchors `dataFile`
 *   and `baseUrl` prefixes `infoUrl`.
 * @param options Plugin options, after `validateOptions`.
 * @returns The Docusaurus plugin instance.
 * @example
 * ```js
 * module.exports = {
 *   plugins: [require.resolve('quickinfo/docusaurus')],
 *   presets: [
 *     [
 *       'classic',
 *       {
 *         docs: {
 *           rehypePlugins: [require('quickinfo/rehype')],
 *         },
 *       },
 *     ],
 *   ],
 * };
 * ```
 */
export default function pluginQuickinfo(context: LoadContext, options: PluginOptions): Plugin {
  const { siteDir, baseUrl } = context;
  const dataFile = options.dataFile ?? DEFAULT_DATA_FILE;
  const dataPath = path.resolve(siteDir, dataFile);
  const outDir = path.join(siteDir, '.docusaurus', 'quickinfo');
  const packedPath = path.join(outDir, 'data.json');
  const configPath = path.join(outDir, 'config.json');
  mkdirSync(outDir, { recursive: true });

  // The client gets the packed index (ids grouped by parent): a large
  // index parses at about half the size. Rewritten on every content load,
  // so `docusaurus start` picks up a regenerated names JSON.
  const writePacked = () => {
    if (!existsSync(dataPath)) {
      // First run before the docs prebuild generated the index: an empty
      // index keeps the site building, with hover inert.
      console.warn(
        `quickinfo: dataFile "${dataFile}" not found; hover disabled until the index is generated.`,
      );
    }
    writeFileSync(packedPath, JSON.stringify(packNames(readNames(dataPath))));
  };
  writePacked();

  // The runtime config is injected as an aliased JSON module, the same
  // mechanism as the data file, so the plugin stays bundler-agnostic
  // (works under webpack and rspack alike).
  writeFileSync(
    configPath,
    JSON.stringify({
      infoUrl: withBase(options.infoUrl || DEFAULT_INFO_URL, baseUrl),
      preferPrefixes: options.preferPrefixes ?? [],
      languages: options.languages ?? ['python'],
      exclude: (options.exclude ?? []).map((prefix) => withBase(prefix, baseUrl)),
    }),
  );

  // Theme components must share the site's @docusaurus/theme-common copy:
  // useCodeBlockContext only works against the provider created by the
  // same module instance, and bundlers resolve imports from the plugin's
  // real path (which may hold a second copy). The alias is exact-match
  // (`$`): a prefix alias would also capture theme-classic's own
  // `@docusaurus/theme-common/*` subpath imports and bypass the package's
  // exports map.
  let themeCommonAliases: Record<string, string> = {};
  try {
    themeCommonAliases = {
      '@docusaurus/theme-common/internal$': require.resolve('@docusaurus/theme-common/internal', {
        paths: [siteDir],
      }),
    };
  } catch {
    console.warn(
      'quickinfo: could not resolve @docusaurus/theme-common; code annotation may be inert.',
    );
  }

  return {
    name: 'quickinfo',

    getThemePath() {
      return path.join(__dirname, 'theme');
    },

    getPathsToWatch() {
      return [dataPath];
    },

    async loadContent() {
      writePacked();
    },

    configureWebpack() {
      // A partial config merged into the site's (object alias form merges
      // per-key with webpack-merge, which is how the site's own aliases
      // are composed). The theme-common alias keeps the plugin's theme
      // components on the site's module instance; the data/config aliases
      // inject the index and the runtime config.
      return {
        resolve: {
          alias: {
            'quickinfo/data$': packedPath,
            'quickinfo/config$': configPath,
            ...themeCommonAliases,
          },
        },
      };
    },
  };
}

/**
 * Validates the plugin options and fills in defaults. Docusaurus calls it
 * before `pluginQuickinfo`.
 *
 * @param options The raw options from `docusaurus.config.js`.
 * @returns The options with every default applied.
 */
export function validateOptions({ options }: { options: unknown }): PluginOptions {
  if (options === undefined) options = {};
  if (typeof options !== 'object' || options === null) {
    throw new Error('quickinfo: options must be an object');
  }
  const raw = options as Record<string, unknown>;
  if (raw.dataFile !== undefined && (typeof raw.dataFile !== 'string' || !raw.dataFile)) {
    throw new Error('quickinfo: "dataFile" must be a path to the generated names JSON');
  }
  checkCommonOptions(raw);
  return {
    dataFile: (raw.dataFile as string | undefined) ?? DEFAULT_DATA_FILE,
    infoUrl: (raw.infoUrl as string | undefined) || DEFAULT_INFO_URL,
    preferPrefixes: (raw.preferPrefixes as string[] | undefined) ?? [],
    languages: (raw.languages as string[] | undefined) ?? ['python'],
    exclude: (raw.exclude as string[] | undefined) ?? [],
  };
}
